package com.nexus.property.profile;
import com.nexus.property.auth.*;import com.nexus.property.core.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/profile") public class ProfileController{private final Db db;public ProfileController(Db db){this.db=db;}private void ensure(String uid){if(db.one("SELECT id FROM user_profiles WHERE user_id=?",uid)==null){long n=System.currentTimeMillis();db.exec("INSERT INTO user_profiles(id,user_id,created_at,updated_at) VALUES(?,?,?,?)",db.uuid(),uid,n,n);}}private Map<String,Object>map(String uid,boolean pub){ensure(uid);var r=db.one("SELECT u.id,u.full_name,u.email,u.phone,u.role,p.* FROM users u LEFT JOIN user_profiles p ON p.user_id=u.id WHERE u.id=?",uid);if(r==null)throw Api.error(404,"User not found.");var m=new LinkedHashMap<String,Object>();m.put("id",Rows.s(r,"id"));m.put("userId",uid);m.put("fullName",Rows.s(r,"full_name"));m.put("role",Rows.s(r,"role"));m.put("profileImageUrl",Rows.s(r,"profile_image_url"));m.put("bio",Rows.s(r,"bio"));m.put("jobTitle",Rows.s(r,"job_title"));m.put("company",Rows.s(r,"company"));m.put("yearsOfExperience",r.get("years_of_experience"));m.put("areasServed",Rows.s(r,"areas_served"));m.put("languages",Rows.s(r,"languages"));m.put("whatsapp",Rows.s(r,"whatsapp"));m.put("address",Rows.s(r,"address"));m.put("city",Rows.s(r,"city"));m.put("country",Rows.s(r,"country"));m.put("preferredContactMethod",Rows.s(r,"preferred_contact_method"));m.put("preferredContactTime",Rows.s(r,"preferred_contact_time"));m.put("phoneVisibility",Rows.s(r,"phone_visibility"));m.put("emailVisibility",Rows.s(r,"email_visibility"));m.put("whatsappVisibility",Rows.s(r,"whatsapp_visibility"));m.put("isVerified",Rows.b(r,"is_verified"));if(!pub||"PUBLIC".equals(Rows.s(r,"email_visibility")))m.put("email",Rows.s(r,"email"));if(!pub||"PUBLIC".equals(Rows.s(r,"phone_visibility")))m.put("phone",Rows.s(r,"phone"));return m;}@GetMapping("/me")public Map<String,Object>me(HttpServletRequest r){var u=AuthFilter.require(r);return Api.ok("Profile retrieved.",map(u.userId(),false));}@GetMapping("/public/{userId}")public Map<String,Object>pub(@PathVariable String userId){return Api.ok("Public profile retrieved.",map(userId,true));}@PutMapping("/personal")public Map<String,Object>personal(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=AuthFilter.require(r);ensure(u.userId());if(b.containsKey("fullName"))db.exec("UPDATE users SET full_name=?,updated_at=? WHERE id=?",b.get("fullName"),System.currentTimeMillis(),u.userId());if(b.containsKey("phone"))db.exec("UPDATE users SET phone=?,updated_at=? WHERE id=?",b.get("phone"),System.currentTimeMillis(),u.userId());for(String k:List.of("address","city","country","whatsapp","preferredContactMethod","preferredContactTime","phoneVisibility","emailVisibility","whatsappVisibility"))if(b.containsKey(k))db.exec("UPDATE user_profiles SET "+snake(k)+"=?,updated_at=? WHERE user_id=?",b.get(k),System.currentTimeMillis(),u.userId());return Api.ok("Personal profile updated.",map(u.userId(),false));}@PutMapping("/professional")public Map<String,Object>professional(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=AuthFilter.require(r);ensure(u.userId());for(String k:List.of("bio","jobTitle","company","yearsOfExperience","areasServed","languages"))if(b.containsKey(k))db.exec("UPDATE user_profiles SET "+snake(k)+"=?,updated_at=? WHERE user_id=?",b.get(k),System.currentTimeMillis(),u.userId());return Api.ok("Professional profile updated.",map(u.userId(),false));}@PostMapping("/photo")public Map<String,Object>photo(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=AuthFilter.require(r);ensure(u.userId());String x=Objects.toString(b.getOrDefault("dataUrl",b.getOrDefault("base64",b.getOrDefault("imageUrl",""))));db.exec("UPDATE user_profiles SET profile_image_url=?,updated_at=? WHERE user_id=?",x,System.currentTimeMillis(),u.userId());return Api.ok("Profile photo updated.",Map.of("profileImageUrl",x));}@DeleteMapping("/photo")public Map<String,Object>del(HttpServletRequest r){var u=AuthFilter.require(r);ensure(u.userId());db.exec("UPDATE user_profiles SET profile_image_url=NULL,updated_at=? WHERE user_id=?",System.currentTimeMillis(),u.userId());return Api.message("Profile photo removed.");}@PutMapping("/admin/verify/{userId}")public Map<String,Object>verify(HttpServletRequest r,@PathVariable String userId,@RequestBody Map<String,Object>b){AuthFilter.role(r,"ADMIN");ensure(userId);boolean v=!b.containsKey("verified")||Boolean.TRUE.equals(b.get("verified"));db.exec("UPDATE user_profiles SET is_verified=?,updated_at=? WHERE user_id=?",v?1:0,System.currentTimeMillis(),userId);return Api.ok("Verification status updated.",map(userId,false));}private String snake(String s){return s.replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase();}}
